export type IsoDashboardSubcategory = {
  id: string;
  label: string;
  /** What this subcategory includes in this inventory. */
  detail: string;
  /** GHG Protocol source that this measured kilogram is reported under. */
  ghgProtocolMapping: string;
  /** Null when this page does not separate the parent total into subcategories. */
  kgCo2e: number | null;
};

export type IsoDashboardCategory = {
  id: string;
  clause: string;
  label: string;
  description: string;
  ghgProtocolMapping: string;
  /** Null when this page does not separate Scope 3 into ISO categories. */
  kgCo2e: number | null;
  notModelled?: boolean;
  subcategories: IsoDashboardSubcategory[];
};

type ScopeBlock = {
  total?: number;
  breakdown?: Record<string, number> | null;
  ghgCategories?: Record<string, number> | null;
} | null | undefined;

type SubDef = {
  id: string;
  label: string;
  detail: string;
  keys: string[];
};

const n = (value: unknown) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

const round2 = (value: number) => Math.round(value * 100) / 100;

const normalizeKey = (key: string) => key.toLowerCase().replace(/[^a-z0-9]/g, '');

const sumKeys = (breakdown: Record<string, number> | null | undefined, keys: string[]) => {
  const wanted = new Set(keys.map(normalizeKey));
  return Object.entries(breakdown || {}).reduce((sum, [key, value]) => (
    wanted.has(normalizeKey(key)) ? sum + n(value) : sum
  ), 0);
};

const hasPositive = (breakdown: Record<string, number> | null | undefined) =>
  Object.values(breakdown || {}).some((value) => n(value) > 0);

