const sub = (def: SubDef, kg: number | null): IsoDashboardSubcategory => ({
  id: def.id,
  label: def.label,
  detail: def.detail,
  ghgProtocolMapping: GHG_MAPPING_BY_SUB_ID[def.id] || '',
  kgCo2e: kg == null ? null : round2(kg),
});

