/**
 * Dashboard view of ISO 14064-1:2018 Clause 5.2.4.
 * Mirrors shared/iso14064ComplianceMetadata.js. Unclassified Scope 3 stays unallocated.
 * When separateScope3 is false, Categories 3, 4 and 6 stay explained and their kilograms stay unset.
 */
export function buildIso14064DashboardCategories(input: {
  scope1?: ScopeBlock;
  scope2?: ScopeBlock;
  scope3?: ScopeBlock;
  separateScope3?: boolean;
}): {
  categories: IsoDashboardCategory[];
  unallocatedScope3Kg: number;
  scope3UnseparatedKg: number;
} {
  const separateScope3 = input.separateScope3 !== false;
  const scope1Kg = n(input.scope1?.total);
  const scope2Kg = n(input.scope2?.total);
  const scope3Kg = n(input.scope3?.total);
  const scope1Breakdown = input.scope1?.breakdown || {};
  const scope2Breakdown = input.scope2?.breakdown || {};
  const ghgCategories = input.scope3?.ghgCategories;
  const scope3Source = hasPositive(ghgCategories) ? ghgCategories : (input.scope3?.breakdown || {});

  const scope1Rows = rowsFromDefs(SCOPE1_SUBS, scope1Breakdown, true);
  const scope1Named = scope1Rows.reduce((sum, row) => sum + n(row.kgCo2e), 0);
  if (scope1Named <= 0 && scope1Kg > 0) {
    scope1Rows.push({
      id: 's1_aggregate',
      label: 'Direct GHG emissions and removals',
      detail: 'The Scope 1 total is not split into stationary, mobile, process, and fugitive sources.',
      ghgProtocolMapping: GHG_MAPPING_BY_SUB_ID.s1_aggregate,
      kgCo2e: round2(scope1Kg),
    });
  } else if (scope1Kg - scope1Named > 0.5) {
    scope1Rows.push({
      id: 's1_other',
      label: 'Other direct GHG emissions and removals',
      detail: 'The rest of Scope 1 after the named sources above.',
      ghgProtocolMapping: GHG_MAPPING_BY_SUB_ID.s1_other,
      kgCo2e: round2(scope1Kg - scope1Named),
    });
  }

  const scope2Rows = rowsFromDefs(SCOPE2_SUBS, scope2Breakdown, true);
  const scope2Named = scope2Rows.reduce((sum, row) => sum + n(row.kgCo2e), 0);
  if (scope2Named <= 0 && scope2Kg > 0) {
    scope2Rows.push({
      id: 's2_location',
      label: 'Imported electricity, heat, steam, and cooling',
      detail: 'The Scope 2 total is not split by energy type.',
      ghgProtocolMapping: GHG_MAPPING_BY_SUB_ID.s2_location,
      kgCo2e: round2(scope2Kg),
    });
  } else if (scope2Kg - scope2Named > 0.5) {
    scope2Rows.push({
      id: 's2_other',
      label: 'Other imported energy',
      detail: 'The rest of Scope 2 after electricity, steam, heat, and cooling.',
      ghgProtocolMapping: GHG_MAPPING_BY_SUB_ID.s2_other,
      kgCo2e: round2(scope2Kg - scope2Named),
    });
  }

  const transportRows = rowsFromDefs(TRANSPORT_SUBS, scope3Source, separateScope3);
  const productRows = rowsFromDefs(PRODUCT_SUBS, scope3Source, separateScope3);
  const useRows = rowsFromDefs(USE_SUBS, scope3Source, separateScope3);
  const otherRows = rowsFromDefs(OTHER_SUBS, scope3Source, separateScope3);

  const cat3Kg = separateScope3 ? transportRows.reduce((sum, row) => sum + n(row.kgCo2e), 0) : 0;
  const cat4Kg = separateScope3 ? productRows.reduce((sum, row) => sum + n(row.kgCo2e), 0) : 0;
  const cat5Kg = separateScope3 ? useRows.reduce((sum, row) => sum + n(row.kgCo2e), 0) : 0;
  const cat6Kg = separateScope3 ? otherRows.reduce((sum, row) => sum + n(row.kgCo2e), 0) : 0;
  const unallocatedScope3Kg = separateScope3
    ? Math.max(0, round2(scope3Kg - cat3Kg - cat4Kg - cat5Kg - cat6Kg))
    : 0;

  const categories: IsoDashboardCategory[] = [
    {
      id: 'cat1_direct',
      clause: 'ISO 14064-1:2018 Category 1',
      label: 'Direct GHG emissions and removals',
      description: 'Emissions from sources the organization owns or controls. Removals, when measured, are reported here too.',
      ghgProtocolMapping: 'GHG Protocol Scope 1.',
      kgCo2e: round2(scope1Kg),
      subcategories: scope1Rows,
    },
    {
      id: 'cat2_imported_energy',
      clause: 'ISO 14064-1:2018 Category 2',
      label: 'Indirect GHG emissions from imported energy',
      description: 'Emissions from generating the electricity, heat, steam, or cooling the organization imports. Transmission and distribution loss is Category 4.',
      ghgProtocolMapping: 'GHG Protocol Scope 2.',
      kgCo2e: round2(scope2Kg),
      subcategories: scope2Rows,
    },
    {
      id: 'cat3_transport',
      clause: 'ISO 14064-1:2018 Category 3',
      label: 'Indirect GHG emissions from transportation',
      description: 'Freight, business travel, and employee commuting outside the organization’s own combustion. People-movement is transportation, so it is not Category 6.',
      ghgProtocolMapping: 'GHG Protocol Scope 3 Categories 4, 6, 7 and 9.',
      kgCo2e: separateScope3 ? round2(cat3Kg) : null,
      subcategories: transportRows,
    },
    {
      id: 'cat4_products_used',
      clause: 'ISO 14064-1:2018 Category 4',
      label: 'Indirect GHG emissions from products used',
      description: 'Purchased goods and services, capital goods, fuel well-to-tank, electricity transmission and distribution loss, and purchased water.',
      ghgProtocolMapping: 'GHG Protocol Scope 3 Categories 1, 2 and 3, plus purchased water.',
      kgCo2e: separateScope3 ? round2(cat4Kg) : null,
      subcategories: productRows,
    },
    {
      id: 'cat5_product_use',
      clause: 'ISO 14064-1:2018 Category 5',
      label: 'Indirect GHG emissions associated with the use of products',
      description: 'Emissions after a sold product leaves the company: further processing by a customer, and use of the product. This category is quantified when a Category 10 or 11 quantity is stored.',
      ghgProtocolMapping: 'GHG Protocol Scope 3 Categories 10 and 11.',
      kgCo2e: separateScope3 ? round2(cat5Kg) : null,
      notModelled: !separateScope3 || cat5Kg <= 0,
      subcategories: useRows,
    },
    {
      id: 'cat6_other',
      clause: 'ISO 14064-1:2018 Category 6',
      label: 'Indirect GHG emissions from other sources',
      description: 'Waste from operations, upstream and downstream leased assets, end-of-life treatment, franchises, and investments. Business travel and commuting stay in Category 3. Purchased water stays in Category 4.',
      ghgProtocolMapping: 'GHG Protocol Scope 3 Categories 5, 8, 12, 13, 14 and 15.',
      kgCo2e: separateScope3 ? round2(cat6Kg) : null,
      subcategories: otherRows,
    },
  ];

  return {
    categories,
    unallocatedScope3Kg,
    scope3UnseparatedKg: separateScope3 ? 0 : round2(scope3Kg),
  };
}
