import React, { useMemo } from 'react';
import { Box, Chip, Stack, Typography } from '@mui/material';
import { formatCo2eFromKg } from '../../constants/carbonVisualization';
import { buildIso14064DashboardCategories } from '../../utils/iso14064DashboardCategories';

type ScopeBlock = {
  total?: number;
  breakdown?: Record<string, number> | null;
  ghgCategories?: Record<string, number> | null;
} | null;

export type Iso14064CategoryStripProps = {
  scope1?: ScopeBlock;
  scope2?: ScopeBlock;
  scope3?: ScopeBlock;
  /** CarbonTwin keeps Scope 3 as one total, so Categories 3–6 stay explained without a split. */
  separateScope3?: boolean;
  /** Ties the categories to the organization boundary on the carbon page, or to twin zones. */
  lead?: string;
  /** Short note under a category, such as which CarbonTwin zone it covers. */
  placementByCategory?: Record<string, string>;
};

const Iso14064CategoryStrip: React.FC<Iso14064CategoryStripProps> = ({
  scope1,
  scope2,
  scope3,
  separateScope3 = true,
  lead,
  placementByCategory,
}) => {
  const view = useMemo(
    () => buildIso14064DashboardCategories({ scope1, scope2, scope3, separateScope3 }),
    [scope1, scope2, scope3, separateScope3]
  );
  const measuredKg = view.categories.reduce((sum, category) => sum + (category.kgCo2e || 0), 0)
    + view.unallocatedScope3Kg
    + view.scope3UnseparatedKg;
  const unit: 'kg' | 't' = measuredKg >= 1000 ? 't' : 'kg';

  return (
    <Box
      component="section"
      data-testid="iso-14064-category-strip"
      aria-label="ISO 14064-1 categories"
      sx={{ mb: 3, p: 2, border: 1, borderColor: 'divider', borderRadius: 2 }}
    >
      <Typography variant="subtitle1" sx={{ fontWeight: 800 }}>
        ISO 14064-1:2018 categories
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5, mb: 2, maxWidth: 760, lineHeight: 1.6 }}>
        {lead || 'Clause 5.2.4 reads the same inventory as the organization boundary, in six categories. Each subcategory says what is included and shows a quantity only when this inventory has one.'}
      </Typography>
      <Stack spacing={2}>
        {view.categories.map((category) => (
          <Box
            key={category.id}
            data-testid={`iso-category-${category.id}`}
            sx={{ pb: 1.5, borderBottom: 1, borderColor: 'divider', '&:last-of-type': { borderBottom: 0, pb: 0 } }}
          >
            <Stack direction="row" spacing={1} alignItems="baseline" flexWrap="wrap" useFlexGap>
              <Typography variant="body2" sx={{ fontWeight: 800 }}>
                {category.clause}
              </Typography>
              <Typography variant="body2" sx={{ fontWeight: 700 }}>
                {category.label}
              </Typography>
              {category.kgCo2e != null ? (
                <Chip size="small" variant="outlined" label={formatCo2eFromKg(category.kgCo2e, { unit })} />
              ) : (
                <Chip size="small" variant="outlined" label="Not separated on this page" />
              )}
              {category.notModelled ? (
                <Chip size="small" label="Not modelled" />
              ) : null}
            </Stack>
            <Typography variant="body2" sx={{ mt: 0.75, lineHeight: 1.6 }}>
              {category.description}
            </Typography>
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
              {category.ghgProtocolMapping}
            </Typography>
            {placementByCategory?.[category.id] ? (
              <Typography variant="caption" display="block" sx={{ mt: 0.5, fontWeight: 700 }}>
                {placementByCategory[category.id]}
              </Typography>
            ) : null}
            <Stack component="ul" spacing={1} sx={{ m: 0, mt: 1, pl: 2.25 }}>
              {category.subcategories.map((subcategory) => (
                <Box component="li" key={subcategory.id} data-testid={`iso-subcategory-${subcategory.id}`}>
                  <Stack direction="row" spacing={1} alignItems="baseline" flexWrap="wrap" useFlexGap>
                    <Typography variant="body2" sx={{ fontWeight: 700 }}>
                      {subcategory.label}
                    </Typography>
                    {subcategory.kgCo2e != null && subcategory.kgCo2e > 0 ? (
                      <Chip
                        size="small"
                        variant="outlined"
                        label={formatCo2eFromKg(subcategory.kgCo2e, { unit })}
                      />
                    ) : null}
                  </Stack>
                  <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.55 }}>
                    {subcategory.detail}
                  </Typography>
                  {subcategory.ghgProtocolMapping ? (
                    <Typography variant="caption" color="text.secondary" display="block" data-testid={`iso-mapping-${subcategory.id}`}>
                      {subcategory.ghgProtocolMapping}
                    </Typography>
                  ) : null}
                </Box>
              ))}
            </Stack>
          </Box>
        ))}
        {view.scope3UnseparatedKg > 0 ? (
          <Typography variant="body2" data-testid="iso-scope3-unseparated">
            Scope 3 on this page is {formatCo2eFromKg(view.scope3UnseparatedKg, { unit })} and is not split into Categories 3, 4, 5 and 6. Those category quantities are on the carbon footprint page, where each activity has a category key.
          </Typography>
        ) : null}
        {view.unallocatedScope3Kg > 0 ? (
          <Typography variant="body2" data-testid="iso-unallocated-scope3" color="warning.main">
            Unallocated Scope 3: {formatCo2eFromKg(view.unallocatedScope3Kg, { unit })}. No category key was present, so no share was assigned.
          </Typography>
        ) : null}
      </Stack>
    </Box>
  );
};

export default Iso14064CategoryStrip;
